    !options.scan &&
    !options.ci &&
    !options.setup &&
    !options.listDocs &&
    !options.clean &&
    !options.update &&
    !options.exportPdf &&
    !options.key;
  if (showConfigOnly) {
    showConfigStatus();
    return;
  }
  await runGenerateFlow(options);
}

