function parseThresholds(thresholdStrings: string[] | undefined): Record<string, number> | null {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const thresholds: Record<string, number> = {};

  for (const threshStr of thresholdStrings) {
    const match = threshStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      log.error(`Invalid threshold format: '${threshStr}'. Expected format: metric=value (e.g., exact_match=0.9)`);
      process.exit(2);
    }

    const [, metricId, valueStr] = match;
    const value = parseFloat(valueStr);

    if (isNaN(value)) {
      log.error(`Invalid threshold value for '${metricId}': '${valueStr}' is not a number.`);
      process.exit(2);
    }

    thresholds[metricId] = value;
  }

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // Parse and validate thresholds if provided
  const thresholds = parseThresholds(options.threshold);
  if (thresholds) {
    const validMetricIds = evaluations.map((m: any) => m.id);
    const validation = (Eval.validateThresholds as unknown as (thresholds: unknown, ids: string[]) => any)(
      thresholds,
      validMetricIds
    );

    if (!validation.valid) {
      log.error('Invalid threshold configuration:');
      validation.errors.forEach((error: string) => {
        console.error(` - ${error}`);
      });
      process.exit(2);
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Exit with appropriate code based on threshold results
  if (report.passed === false) {
    process.exit(1);
  }
}

