    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates threshold values', () => {
    const validMetrics = ['exact_match', 'toxicity', 'length_variance'];

    const valid = validateThresholds({ exact_match: 0.9, toxicity: 1.0 }, validMetrics);
    expect(valid.valid).toBe(true);
    expect(valid.errors).toEqual([]);

    const invalidValue = validateThresholds({ exact_match: 1.5 }, validMetrics);
    expect(invalidValue.valid).toBe(false);
    expect(invalidValue.errors.length).toBeGreaterThan(0);

    const unknownMetric = validateThresholds({ unknown_metric: 0.5 }, validMetrics);
    expect(unknownMetric.valid).toBe(false);
    expect(unknownMetric.errors.some((e) => e.includes('unknown_metric'))).toBe(true);
  });

  it('evaluates thresholds against metrics', () => {
    const metrics = [
      { id: 'exact_match', score: 0.9, label: 'Exact Match', total: 10 },
      { id: 'toxicity', score: 1.0, label: 'Toxicity', total: 10 },
      { id: 'length_variance', score: 0.5, label: 'Length Variance', total: 10 }
    ];

    const result = evaluateThresholds(
      { exact_match: 0.8, toxicity: 1.0, length_variance: 0.7 },
      metrics
    );

    expect(result.passed).toBe(false);
    expect(result.results).toHaveLength(3);
    expect(result.results[0]).toEqual({
      metric: 'exact_match',
      min: 0.8,
      score: 0.9,
      passed: true
    });
    expect(result.results[2]).toEqual({
      metric: 'length_variance',
      min: 0.7,
      score: 0.5,
      passed: false
    });
  });

  it('fails threshold when score is null', () => {
    const metrics = [
      { id: 'exact_match', score: null, label: 'Exact Match', total: 0 }
    ];

    const result = evaluateThresholds({ exact_match: 0.5 }, metrics);

    expect(result.passed).toBe(false);
    expect(result.results[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: null,
      passed: false
    });
  });

  it('generates report with thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9, toxicity: 1.0 }
    });

    expect(report.passed).toBeDefined();
    expect(report.thresholds).toBeDefined();
    expect(report.thresholds.length).toBe(2);
    expect(report.thresholds[0].metric).toBe('exact_match');
  });

  it('does not include thresholds when not provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });

  it('includes thresholds in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
    expect(content).toContain('| Metric | Minimum | Score | Status |');
  });
});

