    outputs: dataset.outputs,
    references: dataset.references
  });

  // Parse and validate thresholds if provided
  const thresholds = parseThresholds(options.threshold);
  if (thresholds) {
    const validMetricIds = evaluations.map((m: any) => m.id);
    const validation = (Eval.validateThresholds as unknown as (thresholds: unknown, ids: string[]) => any)(
      thresholds,
      validMetricIds
    );

    if (!validation.valid) {
      log.error('Invalid threshold configuration:');
      validation.errors.forEach((error: string) => {
        console.error(` - ${error}`);
      });
      process.exit(2);
    }
  }

