it('evaluates thresholds against metrics', () => {
  const metrics = [
    { id: 'exact_match', score: 0.9, label: 'Exact Match', total: 10 },
    { id: 'toxicity', score: 1.0, label: 'Toxicity', total: 10 },
    { id: 'length_variance', score: 0.5, label: 'Length Variance', total: 10 }
  ];

  const result = evaluateThresholds(
    { exact_match: 0.8, toxicity: 1.0, length_variance: 0.7 },
    metrics
  );

  expect(result.passed).toBe(false);
  expect(result.results).toHaveLength(3);
  expect(result.results[0]).toEqual({
    metric: 'exact_match',
    min: 0.8,
    score: 0.9,
    passed: true
  });
  expect(result.results[2]).toEqual({
    metric: 'length_variance',
    min: 0.7,
    score: 0.5,
    passed: false
  });
});

it('fails threshold when score is null', () => {
  const metrics = [
    { id: 'exact_match', score: null, label: 'Exact Match', total: 0 }
  ];

  const result = evaluateThresholds({ exact_match: 0.5 }, metrics);

  expect(result.passed).toBe(false);
  expect(result.results[0]).toEqual({
    metric: 'exact_match',
    min: 0.5,
    score: null,
    passed: false
  });
});

it('generates report with thresholds', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'World'],
    references: ['hello', 'world']
